// ora-mod-plan — generated by tools/merge.js: src/ora-mod-plan-*.js plus matching questions from the Oracle role banks (tools/modules.js).
// Oracle Modules — Planning, Manufacturing & Quality. Format: [topic, question, answer, 'B'|'D']
QB['ora-mod-plan'] = (QB['ora-mod-plan'] || []).concat([
['Planning', 'What is the difference between Supply Planning, Replenishment Planning and Demand Management in Fusion?',
`- **Demand Management**: statistical/ML forecasts, consensus demand plans.
- **Supply Planning**: MRP-style plans netting demand and supply across orgs (make/buy/transfer), constrained or unconstrained.
- **Replenishment Planning**: inventory policies and replenishment for distribution networks (min-max, safety stock optimization).
- **Sales & Operations Planning** ties them to financials.`, 'B'],

['Planning', 'What are planning exceptions and how do planners use them?',
`- Messages like **late replenishment**, **items below safety stock**, **excess**, **past due orders**, **resource overloads**.
- Planners filter by priority and act (expedite, reschedule, release).
- Good planning setups keep exceptions **actionable**, not thousands of noise messages.`, 'D'],

['Planning', 'What is data collection in Fusion planning?',
`- Copies **reference data** (items, orgs, calendars, sourcing) and **transactional data** (on-hand, POs, work orders, sales orders) into the planning data repository.
- **Targeted** (full refresh) vs **net change** collections; scheduled often.
- Stale collections → wrong plans and promise dates.`, 'D'],

['Manufacturing', 'What are work definitions and how do they relate to work orders?',
`- **Work definition**: operations, resources, materials and outputs to make an item (versioned, with priority).
- **Work orders** are created from a work definition (explicitly or by default), inheriting operations and materials.
- Changes to work definitions affect new work orders only.`, 'B'],

['Manufacturing', 'How is material supplied to work orders?',
`- **Supply types**: **Push** (manual issue), **Assembly Pull** (backflush at completion), **Operation Pull** (backflush at operation completion), **Bulk**, **Phantom**.
- Supply subinventory/locator defaults by item/work definition.
- Pick lists/move orders for push materials.`, 'D'],

['Quality', 'What is the Quality Issues and Actions (QIA) flow?',
`- Record **quality issues** (nonconformances) from receiving, production or customers.
- **Investigate**, assign **actions** (corrective/preventive).
- Link to items, lots, suppliers.
- Track closure and effectiveness; analytics for trends.`, 'D'],

['Interview', 'What should a planning/manufacturing contractor be ready to discuss?',
`- Data foundations (lead times, BOMs, sourcing) and collections.
- Plan types and parameters you set.
- Work order execution and costing.
- Integration with MES/quality.
- A story where you improved plan accuracy or reduced inventory.`, 'B']
]);

QB['ora-mod-plan'] = (QB['ora-mod-plan'] || []).concat([["Planning","How would you architect supply chain planning for a global company?","- **Demand Management**: statistical + ML forecasting by product/customer/region; consensus process.\n- **Supply Planning**: constrained plans across plants/DCs; **MPS** for key plants.\n- **Sales & Operations Planning** (Fusion S&OP or IBP process) linking demand, supply and finance.\n- **Replenishment Planning** for DC inventory policies.\n- **Data**: collections from Fusion (and external systems via files), item planning attributes owned by planning.\n- **Cadence**: weekly plan cycles, daily net-change.\n- **Scenarios** for what-if and risk.\n- Integration with **GOP** for promising.","D"],["Planning","What data foundations must be in place before planning can work?","- **Item attributes**: lead times (processing, pre/post), order modifiers, safety stock policy, planning method, make/buy.\n- **BOMs and work definitions** accurate.\n- **Sourcing rules** and assignment sets.\n- **Calendars** (shipping, receiving, manufacturing).\n- **Demand history** clean (returns, promos, stockouts adjusted).\n- **Open supply** accurate (POs, work orders, transfers).\n- **Resource capacities** if constrained planning.\n\nWithout these, the plan produces noise and planners won't trust it.","B"],["Outsourced Manufacturing","How would you model contract manufacturers in Oracle Fusion?","- **Contract manufacturing** (Fusion Outsourced Manufacturing): you own the material and design; the CM builds.\n- Model the CM site as an **inventory org** (contract manufacturing org) with work definitions.\n- **Purchase order** for the CM service tied to a **work order**; components shipped to the CM (or bought by them on your behalf).\n- CM reports progress and completions (B2B messages); finished goods received.\n- **Costing**: material + CM service cost into the assembly.\n- Visibility via supplier portal/B2B.","D"],["Manufacturing","How do you architect manufacturing execution between Fusion and MES?","- **Fusion**: planning, work orders, costing, inventory, quality records of record.\n- **MES**: shop-floor execution detail (machine data, operator steps, electronic batch records in pharma).\n- **Integration**: work orders and BOM/recipes to MES; consumption, completions, labor/machine time, quality results back.\n- **Granularity**: send summaries where detail isn't needed in ERP.\n- **Timing**: near real time for inventory-critical transactions.\n- **Error handling** and reconciliation (WIP balances).","D"],["Maintenance","How does Oracle Maintenance fit into the SCM architecture?","- **Asset maintenance** for equipment: assets, work orders, preventive maintenance schedules, meters.\n- Material for maintenance from **inventory** (MRO spares), purchases via procurement.\n- **Costs** to assets/cost centers; integration with Fixed Assets.\n- **IoT** data can trigger condition-based maintenance.\n- Benefits: uptime, spare parts optimization.","D"],["Quality","How would you architect a closed-loop quality process with Oracle?","- **Inspection plans** at receiving, production and shipping.\n- **Nonconformance** records for failures → **investigation** → **CAPA** (corrective/preventive actions).\n- **Supplier quality**: SCARs, supplier scorecards feeding sourcing decisions.\n- **Change orders** in Product Hub when design/specs change.\n- **Complaints** (customer) linked to lots and genealogy.\n- Analytics on defect trends.","D"],["Planning","What is S&OP and how would you support it with Oracle?","**Sales & Operations Planning** is a monthly business process aligning demand, supply and finance:\n- Demand review → supply review → financial reconciliation → executive S&OP meeting.\n- Oracle **Sales and Operations Planning** (Fusion SCP) provides plans, scenarios, financial views, and collaboration.\n- Integrates demand plans, supply plans and **EPM** financial plans.\n- Outcome: one agreed plan driving execution and finance forecasts.","D"],["Planning","Where does AI help most in Fusion planning, and what are the limits?","- **ML forecasting** and demand sensing; anomaly detection in history.\n- **Exception prioritization** and explanations for planners.\n- **Scenario summaries** for S&OP.\n- **Limits**: poor master data (lead times, BOMs) still breaks plans; planners must understand and own decisions; explainability matters for trust.","D"],["Manufacturing","What is a bill of materials (BOM) and a routing / work definition?","- **BOM / item structure** — the list of components and quantities needed to make an item.\n- **Routing (EBS) / Work definition (Fusion)** — the operations and resources (machines, labor) and their sequence, with component issues assigned to operations.\n- Together they drive **work orders**, **cost rollups** and **planning**.\n\nFusion item structures live in Product Hub; work definitions in Manufacturing.","B"],["Manufacturing","Describe the work order lifecycle in Fusion Manufacturing.","- **Create** the work order (manually, from planning, or for a sales order).\n- **Release** it — components can be picked.\n- **Issue components** (manually, push, or backflush/assembly pull).\n- **Report operations and resources** as work is done.\n- **Complete** the assembly into inventory (and report scrap if any).\n- **Close** the work order — variances are calculated by Cost Management.\n\nStatuses: Unreleased → Released → Completed → Closed (On Hold / Canceled possible).","D"],["Planning","What is the difference between MRP and min-max planning?","- **Min-max** looks only at on-hand and on-order against fixed min/max levels — no forecasts, no BOM explosion.\n- **MRP** (in Fusion Supply Chain Planning) uses **demand** (forecasts, sales orders), **supply** (on-hand, POs, work orders), **BOMs** and **lead times** to calculate what to make or buy and when. It explodes demand through the BOM to components.\n\nUse min-max for simple, stable items; MRP for manufactured items and variable demand.","D"],["Planning","How would you approach implementing Fusion Supply Planning?","- Start with **data readiness**: item planning attributes (lead times, order modifiers, safety stock), BOM and routing accuracy, sourcing rules.\n- **Collections** setup and frequency.\n- Design **plan types** (supply plan, replenishment, MPS) and horizons.\n- Define **exceptions** planners act on; build workflows.\n- **Pilot** a product line; compare recommendations against current planner decisions.\n- Train planners on trust-building — they must see why the plan recommends something.\n- Measure: service level, inventory, expedites.","D"],["Planning","How do you set safety stock?","Methods:\n- **Fixed quantity** or **days of supply**.\n- **Statistical** — based on demand variability, lead time variability and target **service level** (e.g. 95% → z = 1.65).\n- Fusion supports **planning-calculated safety stock** using forecast error.\n\nDecisions: higher service levels for A items and critical customers; lower for C items. Review quarterly — static safety stock goes stale.","D"],["Manufacturing","Discrete vs process manufacturing — what is different in Oracle?","- **Discrete**: items assembled from components (electronics, machinery) — BOMs, routings/work definitions, work orders with operations, serial tracking.\n- **Process**: recipes and formulas with yields, by-products and co-products, batch sizes, potency/grade (chemicals, food, pharma).\n- Fusion supports both: **Discrete Manufacturing** and **Process Manufacturing** (batch work orders with outputs).\n- Costing differs: process manufacturing handles yields and co-product cost allocation.","D"],["Quality","How would you integrate quality inspection into receiving for a regulated company?","- **Inspection receipt routing** for regulated items.\n- **Inspection plans** by item/supplier with sampling (AQL) and specifications.\n- Received material goes to a **quarantine** subinventory/status until QA release.\n- Failures create **nonconformances** and **supplier corrective actions (SCAR)**.\n- **Electronic signatures** for release.\n- Link to supplier performance scores.","D"],["Planning","How do you get planners to trust a new planning system?","- **Clean data** first — wrong lead times destroy trust.\n- Run the new plan **in parallel** and compare recommendations with what planners would do; explain differences.\n- Show **pegging** (why a planned order exists).\n- Start with **exceptions** that matter rather than thousands of messages.\n- Involve senior planners in tuning parameters.\n- Celebrate quick wins (expedites avoided, inventory reduced).","B"],["Manufacturing","How would you approach a Fusion Manufacturing implementation for a mid-size plant?","- **Plant data**: work centers, resources, calendars, item structures, work definitions — validated by engineering.\n- **Work order types** and execution: manual vs backflush; operation reporting granularity (don't overdo it).\n- **Shop floor** devices/tablets; possible **MES** integration.\n- **Costing**: standard cost with resource and overhead rates; variance reporting.\n- **Quality** inspections at key operations.\n- **Planning** feeds (planned orders → work orders).\n- Pilot one production line first.","D"],["Quality","How does Oracle Quality Management support inspections?","- **Inspection plans** define characteristics to check (e.g. dimension, pH), sampling, and acceptance criteria.\n- Triggered at **receiving**, **work order operations**, or **inventory** (ad-hoc).\n- Inspection results are recorded; failures can trigger **issues**, **nonconformances** and **corrective actions**.\n- Rejected material moves to a quarantine status/subinventory.\n\nIntegrated with Receiving (inspection routing) and Manufacturing.","D"],["Planning","Describe how Supply Planning generates planned orders.","- **Data collections** bring on-hand, POs, work orders, sales orders, forecasts, item and BOM data into the planning repository.\n- A **supply plan** runs with plan options (horizon, organizations, demand schedules, constraints).\n- It nets demand against supply, explodes BOMs, applies **lead times**, **order modifiers** (min, max, fixed lot multiple) and **sourcing rules**.\n- Creates **planned orders** (buy, make, transfer) and **recommendations** (reschedule in/out, cancel).\n- Planners review in the Supply Planning work area and **release** planned orders to execution (requisitions, work orders, transfer orders).","D"],["Planning","What are sourcing rules, bills of distribution and assignment sets?","- **Sourcing rule** — for an org (or item), where supply comes from: buy from supplier X (60%) and Y (40%), or transfer from org A. Ranks give priority.\n- **Bill of distribution** — sourcing across multiple orgs (global source chains).\n- **Assignment set** — assigns sourcing rules at different levels: global, org, category, item, item-org. The most specific level wins.\n\nUsed by Planning, GOP, min-max and automatic requisition sourcing.","D"],["Planning","What is the difference between a forecast and a demand plan?","- A **forecast** is a prediction of future demand for items (from history, statistical models or input).\n- A **demand plan** (Demand Management) manages forecasts across levels (product family, region, customer), blends statistical forecasts with sales input and **consensus**, and measures **forecast accuracy**.\n- The approved demand plan feeds the **supply plan** as demand.\n\nGood answer: mention forecast consumption (sales orders consume the forecast to avoid double counting).","D"],["Manufacturing","What is backflushing?","**Backflushing** automatically issues components when an operation or assembly is reported complete, instead of issuing them manually beforehand.\n- **Supply type** on the component: Push (manual issue), **Assembly Pull** (at completion), **Operation Pull** (at operation completion), Bulk, Phantom.\n- Reduces transactions for high-volume, low-value components.\n- Risk: inaccurate on-hand if actual usage differs (scrap) — needs good BOM accuracy and scrap reporting.","D"],["Manufacturing","How is work order cost calculated and how are variances recognized?","- **Standard cost**: assembly valued at standard; actual material, resource and overhead charged to the work order. At **close**, variances are calculated: material usage, resource efficiency, rate variances.\n- **Actual/average cost**: assembly cost = actual costs charged.\n- Accounting: Dr WIP for issues and resources; Cr WIP / Dr Inventory at completion; variances to variance accounts at close.\n\nClosing work orders on time is key for clean month-end costing.","D"],["Planning","How do you mature a company from spreadsheet planning to integrated business planning?","- **Stage 1**: clean data and a single demand plan in the system; basic supply planning.\n- **Stage 2**: constrained supply planning, inventory policies, S&OP process.\n- **Stage 3**: integrated business planning with financial plans, scenario modeling, ML forecasting.\n- **People/process** as important as tools: planning roles, meeting cadence, KPIs.\n- Show value at each stage (forecast accuracy, inventory, service).","D"],["Planning","How would you integrate commercial and supply planning with finance in an IBP process?","- **Common data model**: product families, customers/regions, time buckets aligned with financial calendars.\n- **Demand plan → supply plan → financial projection** (revenue, margin, inventory, cash) using standard costs/prices.\n- **Gaps vs budget** highlighted for executive decisions.\n- **Scenario modeling** (price changes, capacity constraints).\n- **EPM integration** for financial forecasts.\n- **Monthly cadence** with clear decision rights.","D"]]);
